+++ b/tests/Uinsure.Policies.Web.Tests/e2e/N4/dag-1.spec.ts
@@ -0,0 +1,32 @@
+// bug-002 N4 · DAG-1 · the Plan entry of the primary nav (inv-009 #11, I16; David 2026-10-23: fix the nav, not reword
+// the acceptance line). Frame.tsx hard-wires the entry to #/plans/<the first plan of kind build>, so a person who
+// wants the ui plan or an investigation always lands on the build plan first and only then finds the plan tabs.
+// The entry must offer every plan in trace.json before, or without, landing on the build plan.
+// On the `plans` fixture trail (tests/Uinsure.Policies.Web.Tests/fixtures/trails/plans/README.md): build and ui (both `kind: build`, as the
+// real DAGs are) and inv-001.
+import { expect, test } from '@playwright/test';
+import { compileFixture } from '../U0b/support/trail';
+import type { CompiledTrail } from '../U0b/support/trail';
+import { openOnFixture } from '../U1/support/app';
+import { traceAnswered } from '../U5/support/app';
+
+let plans: CompiledTrail;
+test.beforeAll(() => {
+  plans = compileFixture('plans');
+});
+test.afterAll(() => {
+  plans?.trail.cleanup();
+});
+
+test('DAG-1 · activating the Plan nav entry offers build, ui and inv-001 without landing on the build plan', async ({ page }) => {
+  await openOnFixture(page, plans, '/#/');
+  await traceAnswered(page);
+  const nav = page.getByRole('navigation', { name: /^Primary/ });
+  const entry = nav.getByRole('button', { name: /^Plans?\b/ }).or(nav.getByRole('link', { name: /^Plans?$/ })).first();
+  await expect(entry, 'setup: the primary nav has a Plan entry').toBeVisible();
+  await entry.click();
+  for (const id of ['build', 'ui', 'inv-001']) {
+    await expect(page.locator(`a[href="#/plans/${id}"]`).first(), `the Plan entry offers a link to #/plans/${id}`).toBeVisible();
+  }
+  await expect(page, 'the Plan entry has not opened the build plan on its own').not.toHaveURL(/#\/plans\/build$/);
+});
diff --git a/tests/Uinsure.Policies.Web.Tests/unit/screens/dag-1-plan-nav-entry.test.tsx b/tests/Uinsure.Policies.Web.Tests/unit/screens/dag-1-plan-nav-entry.test.tsx
new file mode 100644
index 00000000..24e7d348
--- /dev/null
+++ b/tests/Uinsure.Policies.Web.Tests/unit/screens/dag-1-plan-nav-entry.test.tsx
@@ -0,0 +1,63 @@
+// DAG-1 · the Plan entry of the primary nav offers every plan before, or without, landing on the build plan
+// (bug-002 N4; inv-009 #11, I16; David 2026-10-23: fix the nav, not reword the acceptance line). Frame.tsx's navFor
+// hard-wires the entry to #/plans/<the first plan of kind build>, so the ui plan and the investigations are reached
+// only by first opening the build plan and then its plan tabs.
+// On a small trace written here with two plans of kind build, as the real DAGs are (build and ui), and inv-001.
+import { cleanup, screen, waitFor, within } from '@testing-library/react';
+import userEvent from '@testing-library/user-event';
+import { afterEach, expect, test, vi } from 'vitest';
+import { notFound, renderAppAt } from './support/app';
+
+const SHA = 'd4e5f60718293a4b5c6d7e8f9012345678a1b2c3';
+
+const trace = {
+  schemaVersion: '1.0.0',
+  compiledAt: { ref: 'HEAD', sha: SHA, utc: '2026-10-18T17:00:00Z' },
+  problems: [],
+  rules: [],
+  plans: [
+    { id: 'build', kind: 'build', title: 'Fixture build', nodes: [] },
+    { id: 'ui', kind: 'build', title: 'Fixture ui', nodes: [] },
+    { id: 'inv-001', kind: 'inv', title: 'F2 stub-gate escalation', nodes: [] },
+  ],
+  nodes: [],
+  commits: [],
+  events: [],
+  verdicts: [],
+  findings: [],
+  decisions: [],
+  sessions: [],
+  harness: null,
+};
+
+function serveTrace(): void {
+  vi.stubGlobal('fetch', (input: string) =>
+    Promise.resolve(
+      String(input).endsWith('trace.json')
+        ? new Response(JSON.stringify(trace), { status: 200, headers: { 'content-type': 'application/json' } })
+        : notFound(),
+    ),
+  );
+}
+
+const planHrefs = (): string[] =>
+  [...new Set(Array.from(document.querySelectorAll('a[href^="#/plans/"]')).map((a) => a.getAttribute('href') ?? ''))].filter((href) =>
+    /^#\/plans\/[^/]+$/.test(href),
+  );
+
+afterEach(() => {
+  cleanup();
+  vi.unstubAllGlobals();
+});
+
+test('DAG-1 · activating the Plan nav entry offers build, ui and inv-001 without landing on the build plan', async () => {
+  serveTrace();
+  renderAppAt('');
+  const user = userEvent.setup();
+  await waitFor(() => expect(document.querySelector(`footer a[href$="/commit/${SHA}"]`), 'setup: trace.json has answered').not.toBeNull());
+  const nav = screen.getByRole('navigation', { name: /^Primary/ });
+  const entry = within(nav).queryByRole('button', { name: /^Plans?\b/ }) ?? within(nav).getByRole('link', { name: /^Plans?$/ });
+  await user.click(entry);
+  await waitFor(() => expect(planHrefs().sort(), 'the Plan entry offers every plan').toEqual(['#/plans/build', '#/plans/inv-001', '#/plans/ui']));
+  expect(window.location.hash, 'the Plan entry has not opened the build plan on its own').not.toBe('#/plans/build');
+});

