index 00000000..91660a37
--- /dev/null
+++ b/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-cancel-reset.test.tsx
@@ -0,0 +1,58 @@
+// HONEST-1 · moving from one policy's cancel route straight to another's starts the cancel screen afresh (bug-002 N4;
+// pre-existing on main, found in bug-002/N3 QA step 12). The route table renders one <CancelPolicy /> for
+// workbench/policies/:reference/cancel, so a change of :reference keeps the element and every useState in it: the
+// first policy's quote, its cancel's answer and any stale mark are drawn under the second policy's reference.
+// The first policy, its quote and its cancel are the API's own, recorded in docs/ui/fixture/api/068-… (support/cancel.tsx);
+// the second is the same recorded policy under another reference, read as Active.
+import { act, cleanup, screen, waitFor } from '@testing-library/react';
+import { afterEach, expect, test, vi } from 'vitest';
+import { notFound } from './support/app';
+import { cancelled, openCancel, quoteAndCancel, quoted, quotedDate, soldPolicy } from './support/cancel';
+import { headerStatusText } from './support/header';
+
+const OTHER = 'N4U-OTHER';
+
+const json = (body: unknown, status: number): Response =>
+  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=utf-8' } });
+
+/** The first policy reads as sold, then Cancelled after its cancel; the second always reads Active. */
+function stubTwoPolicies(): void {
+  let firstReads = 0;
+  const first = `/api/policies/${soldPolicy.reference}`;
+  vi.stubGlobal('fetch', async (input: string) => {
+    const path = String(input);
+    if (path === first) {
+      firstReads += 1;
+      return json(firstReads === 1 ? soldPolicy : { ...soldPolicy, status: 'Cancelled' }, 200);
+    }
+    if (path.startsWith(`${first}/cancellation-quote`)) return json(quoted.responseBody, quoted.status);
+    if (path === `${first}/cancellation`) return json(cancelled.responseBody, cancelled.status);
+    if (path === `/api/policies/${OTHER}`) return json({ ...soldPolicy, reference: OTHER, status: 'Active' }, 200);
+    return notFound();
+  });
+}
+
+const mainText = (): string => screen.getByRole('main').textContent?.replace(/\s+/g, ' ') ?? '';
+
+afterEach(() => {
+  cleanup();
+  vi.unstubAllGlobals();
+});
+
+test("HONEST-1 · going from one policy's cancel route straight to another's carries no quote, cancel, answer or stale mark across", async () => {
+  stubTwoPolicies();
+  openCancel();
+  await quoteAndCancel();
+  expect(mainText(), "setup: the first policy's cancel is drawn").toMatch(new RegExp(`Cancelled on ${quotedDate}`));
+
+  await act(async () => {
+    window.location.hash = `#/workbench/policies/${OTHER}/cancel`;
+  });
+  await waitFor(() => expect(headerStatusText(), "setup: the header holds the second policy's status").toContain('Active'));
+
+  expect(mainText(), "no answer of the first policy's cancel is carried").not.toMatch(/Cancelled on/);
+  expect(mainText(), 'no quote of the first policy is carried').not.toMatch(/Quote returned/);
+  expect(screen.queryAllByRole('button', { name: /^Cancel on / }), "no cancel on the first policy's quoted date is offered").toEqual([]);
+  expect((screen.getByLabelText('Cancellation date') as HTMLInputElement).value, "the first policy's date is not carried").toBe('');
+  expect(mainText(), 'no stale mark is carried').not.toMatch(/read before the cancel/i);
+});
diff --git a/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-drawer-rejected-announce.test.tsx b/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-drawer-rejected-announce.test.tsx
new file mode 100644
index 00000000..abfc623d
--- /dev/null
+++ b/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-drawer-rejected-announce.test.tsx
@@ -0,0 +1,60 @@
+// HONEST-1 · a request whose fetch is rejected is announced and tagged as failed in the requests drawer, never
+// "answered" or "Problem" (bug-002 N4; bug-002/N3 review A1 R4, P2). N3 made RequestsDrawer pass `outcome: 'problem'`
+// and a "The request failed" note for it, but the kit InspectorDrawer still announces any outcome but pending as
+// "Request #n answered" and tags a status-less problem "Problem": the API never answered and gave no problem.
+// Sent through the page's own logging fetch (browserDeps) to a fetch that rejects as the browser does.
+import { act, cleanup, render, screen, within } from '@testing-library/react';
+import { afterEach, expect, test, vi } from 'vitest';
+import { RequestsDrawer } from '../../../../src/Uinsure.Policies.Web/app/workbench/RequestsDrawer';
+import { browserDeps } from '../../../../src/Uinsure.Policies.Web/app/workbench/browser';
+import { notFound } from './support/app';
+
+function apiDown(): void {
+  vi.stubGlobal('fetch', async (input: string) => {
+    if (!String(input).startsWith('/api/')) return notFound();
+    throw new TypeError('Failed to fetch');
+  });
+}
+
+async function sendRejected(path: string): Promise<void> {
+  await act(async () => {
+    await browserDeps()
+      .fetch(path, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' })
+      .catch(() => undefined);
+  });
+}
+
+const textOf = (el: Element | null | undefined): string => el?.textContent?.replace(/\s+/g, ' ').trim() ?? '';
+
+afterEach(() => {
+  cleanup();
+  vi.unstubAllGlobals();
+});
+
+/** The drawer, after one rejected sale to `path` is the latest request. */
+async function drawerAfterRejected(path: string): Promise<HTMLElement> {
+  apiDown();
+  render(<RequestsDrawer />);
+  await sendRejected(path);
+  return screen.getByRole('complementary', { name: 'The requests as sent' });
+}
+
+test('HONEST-1 · the requests drawer announces a rejected fetch as failed, never as answered', async () => {
+  const drawer = await drawerAfterRejected('/api/policies/N4U-ANNOUNCE');
+  const announced = textOf(within(drawer).getByRole('status'));
+  expect(announced, 'setup: the drawer announces the latest request').toMatch(/#1/);
+  expect(announced, 'a request that got no response is not announced as answered').not.toMatch(/answered/i);
+  expect(announced, 'the rejected request is announced as failed').toMatch(/fail/i);
+});
+
+test("HONEST-1 · the requests drawer tags a rejected fetch as failed, never 'Problem'", async () => {
+  const drawer = await drawerAfterRejected('/api/policies/N4U-TAG');
+  const item = within(drawer)
+    .getAllByRole('listitem')
+    .find((li) => li.textContent?.includes('/policies/N4U-TAG'));
+  expect(item, 'setup: the drawer lists the rejected request').toBeDefined();
+  const tag = (item as HTMLElement).querySelector('[data-status]');
+  expect(tag, 'setup: the request carries a status tag').not.toBeNull();
+  expect(textOf(tag), 'the API gave no problem, so the tag does not say Problem').not.toMatch(/problem/i);
+  expect(textOf(tag), 'the tag says the request failed').toMatch(/fail/i);
+});
diff --git a/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-status-tone.test.tsx b/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-status-tone.test.tsx
new file mode 100644
index 00000000..66bc86b6
--- /dev/null
+++ b/tests/Uinsure.Policies.Web.Tests/unit/screens/honest-1-status-tone.test.tsx
@@ -0,0 +1,41 @@
+// HONEST-1 · Sell and Cancel draw the header Status in the tone its value earns (bug-002 N4; bug-002/N3 review A1 R3,
+// P2). SellPolicy.tsx draws every sold status as `value: 'pass'`, and CancelPolicy.tsx every read status as
+// `stale ? 'warn' : 'pass'`, so a Pending sale and a Cancelled policy carry a pass tick the API never gave. The policy
+// view already maps each status to a tone (PolicyView.tsx: Pending pending, Active pass, Expired warn, Cancelled
+// fail); the workbench screens must share that one mapping.
+// The sale is the API's own, recorded in docs/ui/fixture/api/003-… (support/sell.ts): Pending. The cancel is
+// 068-… (support/cancel.tsx), its re-read answering the same policy as Cancelled.
+import { cleanup, waitFor } from '@testing-library/react';
+import { afterEach, expect, test, vi } from 'vitest';
+import { openCancel, policyRead, quoteAndCancel, soldPolicy, stubCancel } from './support/cancel';
+import { headerField, headerStatusText } from './support/header';
+import { sellThroughTheScreen, sold } from './support/sell';
+
+afterEach(() => {
+  cleanup();
+  vi.unstubAllGlobals();
+});
+
+/** The tone (kit StatusTag data-status) the live header's Status field is drawn in. */
+const headerTone = (): string | null => headerField('Status')?.querySelector('[data-status]')?.getAttribute('data-status') ?? null;
+
+test("HONEST-1 · after a recorded 201 sale of a Pending policy the sell header's Status is drawn pending, never a pass", async () => {
+  expect(sold.status, 'fixture setup: the recorded sale is Pending').toBe('Pending');
+  await sellThroughTheScreen();
+  await waitFor(() => expect(headerStatusText(), 'setup: the Status field holds the 201 status').toContain('Pending'));
+  expect(headerTone(), 'a Pending policy is not drawn as a pass tick').not.toBe('pass');
+  expect(headerTone(), "Pending is drawn in the policy view's tone for it").toBe('pending');
+});
+
+test("HONEST-1 · after a 201 cancel whose re-read says Cancelled the cancel header's Status is drawn as fail, never a pass", async () => {
+  const cancelledRead = new Response(JSON.stringify({ ...soldPolicy, status: 'Cancelled' }), {
+    status: 200,
+    headers: { 'content-type': 'application/json; charset=utf-8' },
+  });
+  stubCancel([policyRead(), cancelledRead]);
+  openCancel();
+  await quoteAndCancel();
+  await waitFor(() => expect(headerStatusText(), 'setup: the Status field holds the re-read status').toContain('Cancelled'));
+  expect(headerTone(), 'a Cancelled policy is not drawn as a pass tick').not.toBe('pass');
+  expect(headerTone(), "Cancelled is drawn in the policy view's tone for it").toBe('fail');
+});

